from typing import Optional, Dict, Any

from web_utils import parse_content_type, content_charset, image_type


def describe_upload(content_type: str, data: bytes) -> Dict[str, Any]:
    """
    Given a request Content-Type header value and the first bytes of the body, return:
    {
      "mime": <lower-cased media type without parameters>,
      "charset": <lower-cased charset parameter or None>,
      "image": <"png", "jpeg", "gif" or None>  # from signature bytes
    }

    Parameter values may be quoted in the header.
    """
    header = content_type or ""
    mime, _params = parse_content_type(header)  # mime is already lower-cased

    # Preserve "None" when no charset is present.
    try:
        charset = content_charset(header, default=None)
    except Exception:
        # If header parsing fails unexpectedly, fall back safely.
        charset = None
    if charset is not None:
        charset = str(charset).lower()

    detected = image_type(data)  # e.g. 'png', 'jpeg', 'gif', 'bmp', 'webp', or None
    if detected not in ("png", "jpeg", "gif"):
        detected = None

    return {"mime": mime, "charset": charset, "image": detected}

import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently and return results in input order.

    - If a coroutine does not finish within `seconds`, it is cancelled and its result
      position is set to None.
    - Works when called repeatedly in the same process.
    """
    if seconds is None:
        raise TypeError("seconds must be a float (got None)")
    if seconds < 0:
        raise ValueError("seconds must be >= 0")

    async def _runner() -> List[Any]:
        tasks = [asyncio.create_task(c) for c in coros]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED)
            results: List[Any] = [None] * len(tasks)

            for t in done:
                idx = tasks.index(t)  # preserves order mapping; list sizes expected small
                try:
                    results[idx] = t.result()
                except asyncio.CancelledError:
                    results[idx] = None
                except Exception:
                    # If a coroutine errors, propagate like asyncio.gather would.
                    # (Unfinished ones are not relevant once we decide to fail.)
                    raise

            if pending:
                for p in pending:
                    p.cancel()
                # Ensure cancelled tasks are fully processed.
                await asyncio.gather(*pending, return_exceptions=True)

            return results
        finally:
            # Safety: ensure no tasks are left running.
            for t in tasks:
                if not t.done():
                    t.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)

    # No event loop is running in the caller; create a fresh one so repeated calls work.
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(_runner())
    finally:
        try:
            loop.stop()
        finally:
            asyncio.set_event_loop(None)
            loop.close()

from __future__ import annotations

import asyncio
from collections.abc import Awaitable
from typing import Any, List


def run_with_deadline(coros: list[Awaitable[Any]], seconds: float) -> list[Any]:
    """
    Run coroutines concurrently and return results in input order.

    - If a coroutine hasn't finished within `seconds`, it is cancelled and the corresponding
      result is None.
    - Designed to be safe to call repeatedly in the same process.
    - Must be called from synchronous code when no event loop is currently running.
    """
    if seconds is None:
        raise TypeError("seconds must not be None")
    seconds_f = float(seconds)

    # Ensure "ordinary synchronous code" semantics: no running loop.
    try:
        running_loop = asyncio.get_running_loop()
    except RuntimeError:
        running_loop = None
    if running_loop is not None:
        raise PermissionError("run_with_deadline() cannot be called when an event loop is already running")

    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)

        async def runner() -> list[Any]:
            tasks = [loop.create_task(c) for c in coros]

            results: list[Any] = [None] * len(tasks)

            if not tasks:
                return results

            if seconds_f < 0:
                # Negative deadline => treat as immediate timeout
                for t in tasks:
                    if not t.done():
                        t.cancel()
                # Ensure cancellation propagates
                await asyncio.gather(*tasks, return_exceptions=True)
                return results

            try:
                done, pending = await asyncio.wait(tasks, timeout=seconds_f, return_when=asyncio.ALL_COMPLETED)
            except Exception:
                # Defensive: ensure tasks are cleaned up
                for t in tasks:
                    if not t.done():
                        t.cancel()
                await asyncio.gather(*tasks, return_exceptions=True)
                raise

            # Fill completed results
            for idx, task in enumerate(tasks):
                if task in done:
                    exc = task.exception()
                    if exc is None:
                        results[idx] = task.result()
                    else:
                        # Propagate coroutine errors as-is
                        raise exc

            # Cancel anything that didn't finish in time
            for task in tasks:
                if task not in done and not task.done():
                    task.cancel()

            if any(task for task in tasks if task not in done):
                await asyncio.gather(*tasks, return_exceptions=True)

            # results for cancelled tasks remain None
            return results

        return loop.run_until_complete(runner())
    finally:
        try:
            # Cancel any stray tasks created in this loop.
            pending = asyncio.all_tasks(loop)
            for t in pending:
                t.cancel()
            if pending:
                loop.run_until_complete(asyncio.gather(*pending, return_exceptions=True))
        except Exception:
            pass
        finally:
            asyncio.set_event_loop(None)
            loop.close()

from __future__ import annotations

from typing import Optional, Dict, Any

from web_utils import parse_content_type, image_type


def describe_upload(content_type: str, data: bytes) -> dict:
    """
    Given a Content-Type header value and the first bytes of the body, return:
      {
        "mime": <lower-cased media type without parameters>,
        "charset": <lower-cased charset parameter or None>,
        "image": <"png"|"jpeg"|"gif"|None> detected from the data signature
      }

    Parameter values may be quoted.
    """
    if not isinstance(content_type, str):
        raise TypeError(f"content_type must be a str, got {type(content_type).__name__}")
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise TypeError(f"data must be bytes-like, got {type(data).__name__}")

    mime, params = parse_content_type(content_type)
    charset: Optional[str] = params.get("charset")
    if charset is not None:
        charset = str(charset).strip().lower()
        if charset == "":
            charset = None

    detected = image_type(bytes(data))
    image_val = detected if detected in {"png", "jpeg", "gif"} else None

    return {"mime": mime, "charset": charset, "image": image_val}

