import asyncio
from collections.abc import Awaitable
from typing import Any, List


def run_with_deadline(coros: list[Awaitable[Any]], seconds: float) -> list[Any | None]:
    """
    Run coroutines concurrently from ordinary synchronous code (no running event loop
    in this thread). Return results in input order.

    - For any coroutine not finished within `seconds`, return None for it and cancel it.
    - If a finished coroutine raises, the exception is propagated.
    - The function can be called repeatedly in the same process.
    """
    if not isinstance(coros, list):
        raise TypeError("coros must be a list of coroutines/awaitables")
    if not isinstance(seconds, (int, float)) or seconds < 0:
        raise ValueError("seconds must be a non-negative number")

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        pass
    else:
        raise PermissionError("run_with_deadline must be called from synchronous code (no running event loop)")

    items = list(coros)

    async def runner() -> list[Any | None]:
        if not items:
            return []

        tasks = [asyncio.create_task(c) for c in items]
        results: list[Any | None] = [None] * len(items)

        done, pending = await asyncio.wait(tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED)

        # Fill in results for completed tasks (propagate exceptions).
        done_set = {t for t in done}
        for idx, t in enumerate(tasks):
            if t in done_set:
                results[idx] = t.result()  # may raise

        # Cancel and drain pending tasks; ignore their cancellation exceptions.
        if pending:
            for t in pending:
                t.cancel()
            await asyncio.gather(*pending, return_exceptions=True)

        return results

    # Manage our own loop so repeated calls work reliably.
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(runner())
    finally:
        try:
            pending = [t for t in asyncio.all_tasks(loop) if not t.done()]
            if pending:
                for t in pending:
                    t.cancel()
                loop.run_until_complete(asyncio.gather(*pending, return_exceptions=True))
        finally:
            asyncio.set_event_loop(None)
            loop.close()
